import{_ as i,o as s,c as t,a2 as e}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"レート制限","description":"","frontmatter":{},"headers":[],"relativePath":"ja/advanced/ratelimit.md","filePath":"ja/advanced/ratelimit.md","lastUpdated":1784903584000}'),n={name:"ja/advanced/ratelimit.md"};function l(o,a,r,h,d,p){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="レート制限" tabindex="-1">レート制限 <a class="header-anchor" href="#レート制限" aria-label="Permalink to &quot;レート制限&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>swag2mcp には組み込みのレートリミッターがあり、LLM が同じ API エンドポイントを頻繁に呼び出すのを防ぎます。これにより、偶発的な重複呼び出しから保護し、API のレート制限を尊重します。</p><h2 id="仕組み" tabindex="-1">仕組み <a class="header-anchor" href="#仕組み" aria-label="Permalink to &quot;仕組み&quot;">​</a></h2><p>各エンドポイントにはクールダウン期間があります。LLM がクールダウン中に同じエンドポイントを再度呼び出そうとすると、構造化エラーで拒否されます。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0s  → invoke(endpoint) → 実行</span></span>
<span class="line"><span>t=2s  → invoke(endpoint) → rate_limit エラーで拒否</span></span>
<span class="line"><span>t=12s → invoke(endpoint) → 実行（クールダウン経過）</span></span></code></pre></div><h3 id="デフォルトの動作" tabindex="-1">デフォルトの動作 <a class="header-anchor" href="#デフォルトの動作" aria-label="Permalink to &quot;デフォルトの動作&quot;">​</a></h3><ul><li><strong>クールダウン:</strong> エンドポイントあたり 10 秒</li><li><strong>スコープ:</strong> エンドポイントごと — エンドポイント A の呼び出しはエンドポイント B に影響しません</li><li><strong>エラーレスポンス:</strong> LLM はコード <code>rate_limit</code> と待機時間を示すメッセージを含む <code>LLMError</code> を受け取ります</li><li><strong>リセット:</strong> そのエンドポイントで 10 秒間アクティビティがない場合</li></ul><h3 id="エラー形式" tabindex="-1">エラー形式 <a class="header-anchor" href="#エラー形式" aria-label="Permalink to &quot;エラー形式&quot;">​</a></h3><p>レート制限時、LLM は以下を受け取ります：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate_limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate limit exceeded for endpoint </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">: try again in 8 seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Wait for the cooldown period to expire, then try invoking the endpoint again. Use the search tool to find other endpoints you can call in the meantime.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>LLM はこの情報を使用して待機して再試行するか、別のエンドポイントに切り替えることができます。</p><h3 id="なぜ存在するのか" tabindex="-1">なぜ存在するのか <a class="header-anchor" href="#なぜ存在するのか" aria-label="Permalink to &quot;なぜ存在するのか&quot;">​</a></h3><ul><li><strong>偶発的な重複呼び出しを防止</strong> — LLM が同じエンドポイントを短時間に複数回呼び出す可能性があります</li><li><strong>API のレート制限から保護</strong> — 多くの API には独自のレート制限があり、それに達するとエラーが発生します</li><li><strong>リソースを節約</strong> — 不要なネットワークトラフィックを削減します</li></ul><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p>レートリミッターを無効にするか、クールダウン間隔を変更できます：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># レートリミッターを完全に無効化</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_ratelimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># カスタムクールダウン間隔</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rate_limit_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span></code></pre></div><h3 id="disable-ratelimiter" tabindex="-1">disable_ratelimiter <a class="header-anchor" href="#disable-ratelimiter" aria-label="Permalink to &quot;disable_ratelimiter&quot;">​</a></h3><ul><li><strong>型:</strong> <code>bool</code></li><li><strong>デフォルト:</strong> <code>false</code></li><li><strong>効果:</strong> <code>true</code> の場合、エンドポイントごとのレートリミッターが無効になります。LLM は待機なしで同じエンドポイントを繰り返し呼び出せます。</li><li><strong>有効にするタイミング:</strong> テスト、デバッグ、または同じエンドポイントを短時間に複数回呼び出す必要がある場合。</li><li><strong>無効のままにするタイミング（推奨）:</strong> 本番環境。レートリミッターは偶発的な悪用を防ぎます。</li></ul><h3 id="rate-limit-interval" tabindex="-1">rate_limit_interval <a class="header-anchor" href="#rate-limit-interval" aria-label="Permalink to &quot;rate_limit_interval&quot;">​</a></h3><ul><li><strong>型:</strong> 期間（Go 形式：<code>10s</code>、<code>30s</code>、<code>1m</code>）</li><li><strong>デフォルト:</strong> <code>10s</code></li><li><strong>効果:</strong> 同じエンドポイントへの呼び出し間のクールダウン期間を設定します。</li><li><strong>増やすタイミング:</strong> 厳格なレート制限がある API（例：1 分あたり 10 リクエスト）。</li><li><strong>減らすタイミング:</strong> 負荷を制御できる内部 API。</li><li><strong>例:</strong> <code>5s</code>、<code>30s</code>、<code>1m</code>、<code>2m</code></li></ul><h2 id="重要な注意点" tabindex="-1">重要な注意点 <a class="header-anchor" href="#重要な注意点" aria-label="Permalink to &quot;重要な注意点&quot;">​</a></h2><ul><li><strong>エンドポイントごとの追跡</strong> — 各エンドポイントは独立して追跡されます。あるエンドポイントの呼び出しは他に影響しません。</li><li><strong>LLM にエラーが返される</strong> — クールダウン中の 2 回目の呼び出しは <code>rate_limit</code> エラーで拒否されます。LLM はクールダウン期間を受け取り、待機後に再試行できます。</li><li><strong>クリーンアップ不要</strong> — レートリミッターはエンドポイントを自動的に追跡し、メンテナンスは不要です。</li></ul>`,23)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
